import{_ as p,a0 as l,w as o,s as d,I as t,x as n,a1 as a,A as i,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 上设置时间同步 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上设置时间同步 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上设置时间同步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上设置时间同步 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190805 How To Set Up Time Synchronization On Ubuntu","title":"如何在 Ubuntu 上设置时间同步","tag":"201908","desc":""},"relativePath":"201908/20190805 How To Set Up Time Synchronization On Ubuntu.md","filePath":"[post].md"}'),u={name:"201908/20190805 How To Set Up Time Synchronization On Ubuntu.md"};function r(h,s,g,m,b,k){const e=l("Link");return o(),d("div",null,[s[22]||(s[22]=t("h1",{id:"如何在-ubuntu-上设置时间同步",tabindex:"-1"},[n("如何在 Ubuntu 上设置时间同步 "),t("a",{class:"header-anchor",href:"#如何在-ubuntu-上设置时间同步","aria-label":"Permalink to “如何在 Ubuntu 上设置时间同步”"},"​")],-1)),s[23]||(s[23]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/201908/13/135423xnk7zib00nn2aebv.jpg",alt:""})],-1)),t("p",null,[s[2]||(s[2]=n("你可能设置过 ",-1)),a(e,{href:"https://www.ostechnix.com/a-beginners-guide-to-cron-jobs/"},{default:i(()=>[...s[0]||(s[0]=[n("cron 任务",-1)])]),_:1}),s[3]||(s[3]=n(" 来在特定时间备份重要文件或执行系统相关任务。也许你配置了一个日志服务器在特定时间间隔",-1)),a(e,{href:"https://www.ostechnix.com/manage-log-files-using-logrotate-linux/"},{default:i(()=>[...s[1]||(s[1]=[n("轮转日志",-1)])]),_:1}),s[4]||(s[4]=n("。但如果你的时钟不同步，这些任务将无法按时执行。这就是要在 Linux 系统上设置正确的时区并保持时钟与互联网同步的原因。本指南介绍如何在 Ubuntu Linux 上设置时间同步。下面的步骤已经在 Ubuntu 18.04 上进行了测试，但是对于使用 systemd 的 ",-1)),s[5]||(s[5]=t("code",null,"timesyncd",-1)),s[6]||(s[6]=n(" 服务的其他基于 Ubuntu 的系统它们是相同的。",-1))]),s[24]||(s[24]=c(`<h3 id="在-ubuntu-上设置时间同步" tabindex="-1">在 Ubuntu 上设置时间同步 <a class="header-anchor" href="#在-ubuntu-上设置时间同步" aria-label="Permalink to “在 Ubuntu 上设置时间同步”">​</a></h3><p>通常，我们在安装时设置时区。但是，你可以根据需要更改或设置不同的时区。</p><p>首先，让我们使用 <code>date</code> 命令查看 Ubuntu 系统中的当前时区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tue Jul 30 11:47:39 UTC 2019</span></span></code></pre></div><p>如上所见，<code>date</code> 命令显示实际日期和当前时间。这里，我当前的时区是 <strong>UTC</strong>，代表<strong>协调世界时</strong>。</p><p>或者，你可以在 <code>/etc/timezone</code> 文件中查找当前时区。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/timezone</span></span>
<span class="line"><span>UTC</span></span></code></pre></div><p>现在，让我们看看时钟是否与互联网同步。只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Local time: Tue 2019-07-30 11:53:58 UTC</span></span>
<span class="line"><span>Universal time: Tue 2019-07-30 11:53:58 UTC</span></span>
<span class="line"><span>RTC time: Tue 2019-07-30 11:53:59</span></span>
<span class="line"><span>Time zone: Etc/UTC (UTC, +0000)</span></span>
<span class="line"><span>System clock synchronized: yes</span></span>
<span class="line"><span>systemd-timesyncd.service active: yes</span></span>
<span class="line"><span>RTC in local TZ: no</span></span></code></pre></div><p>如你所见，<code>timedatectl</code> 命令显示本地时间、世界时、时区以及系统时钟是否与互联网服务器同步，以及 <code>systemd-timesyncd.service</code> 是处于活动状态还是非活动状态。就我而言，系统时钟已与互联网时间服务器同步。</p><p>如果时钟不同步，你会看到下面截图中显示的 <code>System clock synchronized: no</code>。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/timedatectl-command-output-ubuntu.jpeg" alt=""></p><p><em>时间同步已禁用。</em></p><p>注意：上面的截图是旧截图。这就是你看到不同日期的原因。</p><p>如果你看到 <code>System clock synchronized:</code> 值设置为 <code>no</code>，那么 <code>timesyncd</code> 服务可能处于非活动状态。因此，只需重启服务并看下是否正常。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart systemd-timesyncd.service</span></span></code></pre></div><p>现在检查 <code>timesyncd</code> 服务状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status systemd-timesyncd.service</span></span>
<span class="line"><span>● systemd-timesyncd.service - Network Time Synchronization</span></span>
<span class="line"><span>Loaded: loaded (/lib/systemd/system/systemd-timesyncd.service; enabled; vendor preset: enabled)</span></span>
<span class="line"><span>Active: active (running) since Tue 2019-07-30 10:50:18 UTC; 1h 11min ago</span></span>
<span class="line"><span>Docs: man:systemd-timesyncd.service(8)</span></span>
<span class="line"><span>Main PID: 498 (systemd-timesyn)</span></span>
<span class="line"><span>Status: &quot;Synchronized to time server [2001:67c:1560:8003::c7]:123 (ntp.ubuntu.com).&quot;</span></span>
<span class="line"><span>Tasks: 2 (limit: 2319)</span></span>
<span class="line"><span>CGroup: /system.slice/systemd-timesyncd.service</span></span>
<span class="line"><span>└─498 /lib/systemd/systemd-timesyncd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Jul 30 10:50:30 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:31 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:31 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:32 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:32 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:35 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:35 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:35 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:50:35 ubuntuserver systemd-timesyncd[498]: Network configuration changed, trying to estab</span></span>
<span class="line"><span>Jul 30 10:51:06 ubuntuserver systemd-timesyncd[498]: Synchronized to time server [2001:67c:1560:800</span></span></code></pre></div><p>如果此服务已启用并处于活动状态，那么系统时钟应与互联网时间服务器同步。</p><p>你可以使用命令验证是否启用了时间同步：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl</span></span></code></pre></div><p>如果仍然不起作用，请运行以下命令以启用时间同步：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo timedatectl set-ntp true</span></span></code></pre></div><p>现在，你的系统时钟将与互联网时间服务器同步。</p><h4 id="使用-timedatectl-命令更改时区" tabindex="-1">使用 timedatectl 命令更改时区 <a class="header-anchor" href="#使用-timedatectl-命令更改时区" aria-label="Permalink to “使用 timedatectl 命令更改时区”">​</a></h4><p>如果我想使用 UTC 以外的其他时区怎么办？这很容易！</p><p>首先，使用命令列出可用时区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl list-timezones</span></span></code></pre></div><p>你将看到类似于下图的输出。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/List-timezones-using-timedatectl-command.png" alt=""></p><p><em>使用 timedatectl 命令列出时区</em></p><p>你可以使用以下命令设置所需的时区（例如，Asia/Shanghai）：</p><p>（LCTT 译注：本文原文使用印度时区作为示例，这里为了便于使用，换为中国标准时区 CST。另外，在时区设置中，要注意 CST 这个缩写会代表四个不同的时区，因此建议使用城市和 UTC+8 来说设置。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo timedatectl set-timezone Asia/Shanghai</span></span></code></pre></div><p>使用 <code>date</code> 命令再次检查时区是否已真正更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date</span></span>
<span class="line"><span>Tue Jul 30 20:22:33 CST 2019</span></span></code></pre></div><p>或者，如果需要详细输出，请使用 <code>timedatectl</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl</span></span>
<span class="line"><span>Local time: Tue 2019-07-30 20:22:35 CST</span></span>
<span class="line"><span>Universal time: Tue 2019-07-30 12:22:35 UTC</span></span>
<span class="line"><span>RTC time: Tue 2019-07-30 12:22:36</span></span>
<span class="line"><span>Time zone: Asia/Shanghai (CST, +0800)</span></span>
<span class="line"><span>System clock synchronized: yes</span></span>
<span class="line"><span>systemd-timesyncd.service active: yes</span></span>
<span class="line"><span>RTC in local TZ: no</span></span></code></pre></div><p>如你所见，我已将时区从 UTC 更改为 CST（中国标准时间）。</p><p>要切换回 UTC 时区，只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo timedatectl set-timezone UTC</span></span></code></pre></div><h4 id="使用-tzdata-更改时区" tabindex="-1">使用 tzdata 更改时区 <a class="header-anchor" href="#使用-tzdata-更改时区" aria-label="Permalink to “使用 tzdata 更改时区”">​</a></h4><p>在较旧的 Ubuntu 版本中，没有 <code>timedatectl</code> 命令。这种情况下，你可以使用 <code>tzdata</code>（Time zone data）来设置时间同步。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg-reconfigure tzdata</span></span></code></pre></div><p>选择你居住的地理区域。对我而言，我选择 <strong>Asia</strong>。选择 OK，然后按回车键。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/configure-time-zone-using-tzdata-1.png" alt=""></p><p>接下来，选择与你的时区对应的城市或地区。这里，我选择了 <strong>Kolkata</strong>（LCTT 译注：中国用户请相应使用 Shanghai 等城市）。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/configure-time-zone-using-tzdata-2.png" alt=""></p><p>最后，你将在终端中看到类似下面的输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Current default time zone: &#39;Asia/Shanghai&#39;</span></span>
<span class="line"><span>Local time is now: Tue Jul 30 21:59:25 CST 2019.</span></span>
<span class="line"><span>Universal Time is now: Tue Jul 30 13:59:25 UTC 2019.</span></span></code></pre></div><h4 id="在图形模式下配置时区" tabindex="-1">在图形模式下配置时区 <a class="header-anchor" href="#在图形模式下配置时区" aria-label="Permalink to “在图形模式下配置时区”">​</a></h4><p>有些用户可能对命令行方式不太满意。如果你是其中之一，那么你可以轻松地在图形模式的系统设置面板中进行设置。</p><p>点击 Super 键（Windows 键），在 Ubuntu dash 中输入 <strong>settings</strong>，然后点击设置图标。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/System-settings-Ubuntu-dash.png" alt=""></p><p><em>从 Ubuntu dash 启动系统的设置</em></p><p>或者，单击位于 Ubuntu 桌面右上角的向下箭头，然后单击左上角的“设置”图标。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Ubuntu-system-settings.png" alt=""></p><p><em>从顶部面板启动系统的设置</em></p><p>在下一个窗口中，选择“细节”，然后单击“日期与时间”选项。打开“自动的日期与时间”和“自动的时区”。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Set-automatic-timezone-in-ubuntu.png" alt=""></p><p><em>在 Ubuntu 中设置自动时区</em></p><p>关闭设置窗口就行了！你的系统始终应该与互联网时间服务器同步了。</p><hr>`,67)),t("p",null,[s[8]||(s[8]=n("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-set-up-time-synchronization-on-ubuntu/"},{default:i(()=>[...s[7]||(s[7]=[n("https://www.ostechnix.com/how-to-set-up-time-synchronization-on-ubuntu/",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=n("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...s[9]||(s[9]=[n("sk",-1)])]),_:1}),s[14]||(s[14]=n(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[10]||(s[10]=[n("lujun9972",-1)])]),_:1}),s[15]||(s[15]=n(" 译者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[11]||(s[11]=[n("geekpi",-1)])]),_:1}),s[16]||(s[16]=n(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[12]||(s[12]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=n("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[17]||(s[17]=[n("LCTT",-1)])]),_:1}),s[20]||(s[20]=n(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:i(()=>[...s[18]||(s[18]=[n("Linux中国",-1)])]),_:1}),s[21]||(s[21]=n(" 荣誉推出",-1))])])}const C=p(u,[["render",r]]);export{T as __pageData,C as default};
